# FDN Flamewake Phoenix: "Flying, haste. This creature attacks each combat if able. Ferocious — At the
# beginning of combat on your turn, if you control a creature with power 4 or greater, you may pay
# {R}. If you do, return this card from your graveyard to the battlefield."
# [0]: M20 Rubblebelt Recluse's verified MANDATE_ATTACK static, word for word.
# [1]: Dire Fleet Warmonger's verified "beginning of combat on your turn"; the intervening "if" is
# the condition, M21 Furious Rise's verified "if you control a creature with power 4 or greater";
# effect: Ghostly Pilferer's "you may pay ... If you do, ..." at {R}, then M21 Silversmote Ghoul's
# verified "return this card from your graveyard to the battlefield" (untapped here). The effect moves
# its own card out of the graveyard, so the ability works only there (CR 113.6m,
# binding.functions_from_graveyard). Flying and haste are compiled.
must_attack = StaticAbility(
    effect=A(Verb.MANDATE_ATTACK, {
        'cards': Selector(
            count=QConst(value=1),
            mode=SelectorMode.CHOOSE,
            filter=FAtom(pred=FAtomPred.IS_SOURCE),
            zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
        ),
    }),
)
ferocious = TriggeredAbility(
    event=TurnPhaseEvent(
        phase=Phase.COMBAT,
        actor=FAtom(pred=FAtomPred.CONTROLLER_IS, who=ControllerRef.YOU),
    ),
    condition=FAtom(
        pred=FAtomPred.CONTROLLER_COUNT_GE,
        count=QConst(value=1),
        inner_filter=FAnd(
            children=(
                FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
                FAtom(pred=FAtomPred.POWER_GE, count=QConst(value=4)),
            ),
        ),
    ),
    effect=Seq(
        steps=(
            OptionalEffect(
                inner=A(Verb.PAY, {
                    'cost': Cost(parts=(CostManaColor(color='R', amount=QConst(value=1)),)),
                }),
            ),
            Conditional(
                pred=FAtom(pred=FAtomPred.MAY_DONE),
                then_effect=A(Verb.MOVE_ZONE, {
                    'cards': Selector(
                        count=QConst(value=1),
                        mode=SelectorMode.CHOOSE,
                        filter=FAtom(pred=FAtomPred.IS_SOURCE),
                        zones=(Zone(kind=ZoneKind.GRAVEYARD, controller=ControllerRef.YOU),),
                    ),
                    'destination': Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.YOU),
                }),
            ),
        ),
    ),
)
abilities = [must_attack, ferocious, *compiled]
